import {stories,characters,difficulties} from './story.js';
import {createProgressStore} from './progress.js';
import {isCorrect,makePieces,placePiece,cleanProgress} from './engine.js';
import {chime,speak,stopSpeech} from './audio.js';
import {attachDrag} from './drag.js';
import {createAutoCheck} from './auto-check.js';
import {createMathUI} from './math-ui.js';

const app=document.querySelector('#app');
let story=stories[0];
let levelFilter='todos';
const levelInfo=book=>difficulties.find(d=>d.id===book.difficulty);
let storage;try{storage=window.localStorage;}catch{}
const progressStore=createProgressStore(storage,stories);
const getProgress=book=>progressStore.get(book.id);
const read=(k,fallback)=>{try{return JSON.parse(localStorage.getItem(k))??fallback;}catch{return fallback;}};
let progress=getProgress(story);
let settings={sound:true,uppercase:true,...read('conta-encanta:settings',{})};
let renderedView=null,homeScroll=0;const shelfScroll=new Map();
let view='home',pageIndex=progress.current,slots=[],selected=[],solved=false,feedback='',hint=false,cleanupDrag=()=>{},modal=null;
const automatic=createAutoCheck({ready:()=>view==='book'&&!solved&&answerReady(),check:checkAnswer});
const mathUI=createMathUI({storage,onRender:()=>render(),onNavigate:target=>{automatic.cancel();stopSpeech();modal=null;view=target;render();window.scrollTo(0,0);},talk:text=>talk(text),play:success=>chime(settings.sound,success),celebrate:()=>confetti()});
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const letter=s=>settings.uppercase?s.toLocaleUpperCase('pt-BR'):s;
const save=()=>{progressStore.save(story.id,progress);try{storage?.setItem('conta-encanta:settings',JSON.stringify(settings));}catch{/* Sem armazenamento, segue funcionando nesta sessão. */}};
const icon=(type)=>({book:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 5v15M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2Z"/></svg>',sound:'♪',settings:'⚙',home:'⌂'}[type]||type);
const header=()=>`<header class="site-header"><button class="brand" data-action="home" aria-label="Conta e Encanta, início"><span class="brand-mark">${icon('book')}</span><span>conta<span class="brand-and"> & </span>encanta<small>PEQUENAS LEITURAS. GRANDES AVENTURAS.</small></span></button><nav aria-label="Opções"><button class="icon-button sound-toggle ${settings.sound?'':'muted'}" data-action="sound" aria-label="${settings.sound?'Desligar':'Ligar'} sons" title="${settings.sound?'Desligar':'Ligar'} sons">${settings.sound?'♫':'♩'}<span class="desktop-label">${settings.sound?'Som ligado':'Sem som'}</span></button><button class="icon-button" data-action="settings" aria-label="Abrir opções para responsáveis">${icon('settings')}</button></nav></header>`;
const footer=()=>`<footer>Feito para aprender no seu tempo. <span>Uma palavra de cada vez.</span><span class="footer-flower">✿</span></footer>`;
function bookCard(item,index){
  const state=getProgress(item),begun=state.completed.length>0,finished=state.completed.length===item.pages.length;
  return `<button class="book-card featured-book" data-book="${item.id}"><div class="book-cover"><img src="/assets/${item.cover}" alt="${escape(item.coverAlt)}" loading="lazy"><span class="book-label">${finished?'LIVRO CONCLUÍDO ✓':begun?'CONTINUE DE ONDE PAROU':item.id===stories[0].id?'SEU PRIMEIRO LIVRO':'NOVA AVENTURA'}</span></div><div class="book-info"><span class="difficulty-badge level-${item.difficulty}">${levelInfo(item).label}</span><span class="book-kind">${item.tagline}</span><h3>${escape(item.title)}</h3><div class="book-bottom"><span>${item.pages.length} páginas interativas</span><span class="round-arrow">↗</span></div>${begun?`<div class="mini-progress"><i style="width:${state.completed.length/item.pages.length*100}%"></i></div>`:''}</div></button>`;
}
function library(){
  const visible=difficulties.filter(d=>levelFilter==='todos'||d.id===levelFilter);
  return `<div class="level-filters" role="group" aria-label="Filtrar livros por dificuldade"><button data-level="todos" class="level-filter ${levelFilter==='todos'?'active':''}" aria-pressed="${levelFilter==='todos'}">Todos <span>${stories.length}</span></button>${difficulties.map(d=>`<button data-level="${d.id}" class="level-filter ${levelFilter===d.id?'active':''}" aria-pressed="${levelFilter===d.id}">${d.label} <span>${stories.filter(s=>s.difficulty===d.id).length}</span></button>`).join('')}</div><p class="level-guidance">Escolha um desafio no seu ritmo. Todos os livros têm áudio e pistas para ajudar.</p>${visible.map(d=>`<section class="level-section" aria-label="Livros de nível ${d.label}"><div class="level-heading"><h3><span class="difficulty-badge level-${d.id}">${d.label}</span></h3><p>${d.description}</p></div><div class="carousel-toolbar"><span>Deslize para descobrir os 7 livros <span aria-hidden="true">↔</span></span><div class="carousel-controls" role="group" aria-label="Navegar pelos livros de nível ${d.label}"><button class="carousel-arrow" data-carousel="${d.id}" data-direction="-1" aria-label="Livros anteriores, nível ${d.label}" aria-controls="books-${d.id}">←</button><button class="carousel-arrow" data-carousel="${d.id}" data-direction="1" aria-label="Próximos livros, nível ${d.label}" aria-controls="books-${d.id}">→</button></div></div><div class="books-carousel" id="books-${d.id}" role="region" aria-label="Carrossel de livros: ${d.label}">${stories.filter(s=>s.difficulty===d.id).map(bookCard).join('')}</div></section>`).join('')}`;
}
function home(){
  const begun=progress.completed.length>0,finished=progress.completed.length===story.pages.length;
  return `${header()}<main class="home-main"><section class="hero"><div class="hero-copy"><span class="eyebrow"><span class="small-star">✦</span> HISTÓRIAS E NÚMEROS PARA BRINCAR E APRENDER</span><h1>Uma história.<br> Mil descobertas.<br><em>E você no meio.</em></h1><p>Entre no mundo da nossa turma maluquinha.<br class="desktop-only"> Junte sílabas, descubra palavras e ajude a história a acontecer.</p><button class="primary large" data-action="start">${finished?'Ler outra vez':begun?'Continuar a aventura':'Abrir meu primeiro livro'} <span>↗</span></button><div class="hero-meta"><span>☀ No seu nível</span><span>◷ No seu ritmo</span><span>♡ Sem competição</span></div></div><div class="hero-art"><div class="art-frame"><img src="/assets/cast.webp" alt="Capitu, Pipo, Lulu e Tito, a turma do Conta e Encanta" fetchpriority="high"><span class="art-sticker">Uma turma<br><strong>nada comum!</strong><i>✦</i></span></div><span class="art-caption">QUATRO AMIGOS. UM MUNDO DE IMAGINAÇÃO.</span></div></section><section class="math-invite"><img src="/assets/math-fair.webp" alt="A turma na feira de matemática" loading="lazy"><div><span class="eyebrow">UMA NOVA FORMA DE DESCOBRIR</span><h2>Matemática com a turma</h2><p>Sete desafios com blocos, cestas, bolachas e uma lojinha. Para explorar dos 7 aos 10 anos.</p><button class="primary" data-action="math-home">${mathUI.completed?'Continuar com os números':'Explorar os números'} <span>↗</span></button><small>${mathUI.completed} de 7 desafios descobertos</small></div></section><section class="books-section" id="library"><div class="section-heading"><div><span class="eyebrow">SUA PEQUENA BIBLIOTECA</span><h2>Qual aventura vamos viver?</h2></div><span class="shelf-note">Histórias que você ajuda a contar <span>↙</span></span></div>${library()}</section><section class="meet-section"><div><span class="eyebrow">AMIGOS PARA CADA DESCOBERTA</span><h2>Conheça a turma</h2></div><div class="character-grid">${characters.map((c,i)=>`<button class="character-card" data-action="character" data-index="${i}" style="--character-color:${c.color}"><span class="character-portrait portrait-${i}"></span><strong>${c.name}</strong><span>${c.description}</span><small>Ouvir apresentação ♫</small></button>`).join('')}</div></section><section class="parent-note"><span>♡</span><div><strong>Aprender pode ser uma boa história.</strong><p>Sem pressa, sem vidas perdidas. A criança pode tentar, pedir uma pista e descobrir de novo.</p></div><button class="text-button" data-action="settings">Para responsáveis ↗</button></section></main>${footer()}`;
}
function activity(page){
  if(page.type==='sequence'){
    const pieces=makePieces(page);
    return `<div class="slots ${page.sequenceUnit==='sentence'?'sentence-slots':''}" aria-label="Sua resposta">${slots.map((id,i)=>{const piece=pieces.find(p=>p.id===id);return `<button class="slot ${id?'filled':''}" data-slot="${i}" ${piece?`data-piece="${piece.id}"`:''} ${solved?'disabled':''} aria-label="${piece?`Retirar ${piece.label}`:`Espaço ${i+1}: solte uma peça aqui`}">${piece?escape(letter(piece.label)):`<span>${i+1}</span>`}</button>`;}).join('')}</div><div class="pieces ${page.sequenceUnit==='sentence'?'sentence-pieces':''}" aria-label="Peças para montar">${pieces.filter(p=>!slots.includes(p.id)).map(p=>`<button class="piece" data-piece="${p.id}" ${solved?'disabled':''}>${escape(letter(p.label))}</button>`).join('')}</div><p class="interaction-tip">Arraste as peças ou toque nelas. Ao completar, o app confere sozinho.</p>`;
  }
  return `${page.prompt?`<p class="reading-sentence">${escape(letter(page.prompt))}${page.blank?` <span class="blank-word">${selected[0]?escape(letter(selected[0])):'…'}</span>${escape(page.suffix||'')}`:''}</p>`:''}${page.type==='count'?`<div class="banana-count" aria-label="Objetos para contar">${Array.from({length:page.count},(_,i)=>`<button class="count-fruit" data-action="fruit" data-index="${i}" aria-label="${escape(page.countNoun||'objeto')} ${i+1}">${page.countIcon||'🍌'}</button>`).join('')}</div>`:''}<div class="choices ${page.choices.some(c=>c.label.length>20)?'written-choices':''}">${page.choices.map(c=>`<button class="choice ${selected[0]===c.label?'selected':''}" data-choice="${escape(c.label)}" aria-pressed="${selected[0]===c.label}" ${solved?'disabled':''}>${c.icon?`<span>${c.icon}</span>`:''}${escape(letter(c.label))}</button>`).join('')}</div>`;
}
function book(){const page=story.pages[pageIndex];return `${header()}<main class="reader-main"><div class="reader-top"><button class="text-button" data-action="home">← Biblioteca</button><span>${escape(story.title)}<small class="reader-level">${levelInfo(story).label}</small></span><button class="text-button" data-action="settings" aria-label="Opções de leitura">Aa</button></div><div class="chapter-track" aria-label="Páginas do livro">${story.pages.map((p,i)=>`<button class="chapter-dot ${i===pageIndex?'active':''} ${progress.completed.includes(i)?'done':''}" data-page="${i}" ${i>0&&!progress.completed.includes(i-1)?'disabled':''} aria-label="Página ${i+1}: ${p.chapter}" ${i===pageIndex?'aria-current="step"':''}>${progress.completed.includes(i)?'✓':i+1}</button>`).join('')}</div><article class="storybook"><section class="story-scene"><img src="/assets/${page.image}" alt="${escape(page.alt)}"><div class="scene-shade"></div><span class="page-badge">PÁGINA ${pageIndex+1} DE ${story.pages.length}</span><button class="scene-audio" data-action="narrate" aria-label="Ouvir história" ${!settings.sound?'disabled':''}>♫ <span>Ouvir história</span></button><div class="scene-copy"><h1>${page.chapter}</h1><p class="story-narration">${escape(letter(page.narration))}</p></div><button class="scene-spark" data-action="spark" aria-label="Uma surpresa da turma">✦</button></section><section class="activity-panel ${page.readingText?'reading-activity':''}"><div class="activity-heading"><span class="eyebrow">${['sequence'].includes(page.type)?'VAMOS MONTAR?':page.type==='count'?'VAMOS CONTAR?':'VAMOS DESCOBRIR?'}</span><button class="small-audio" data-action="instruction" aria-label="Ouvir instrução" ${!settings.sound?'disabled':''}>♫</button></div>${page.readingText?`<div class="reading-passage"><div><span>LEIA O TRECHO</span><button class="small-audio" data-action="passage" aria-label="Ouvir trecho" ${!settings.sound?'disabled':''}>♫</button></div><p>${escape(letter(page.readingText))}</p></div>`:''}<h2>${page.instruction}</h2>${activity(page)}<div class="feedback ${solved?'success':feedback?'encouragement':''}" role="status">${feedback?`<span>${solved?'✦':'♡'}</span> ${escape(letter(feedback))}`:'<span class="quiet-feedback">Você pode tentar quantas vezes quiser.</span>'}</div>${hint?`<div class="hint-box">💡 ${escape(letter(page.hint))}</div>`:''}<div class="activity-actions"><button class="hint-button" data-action="hint" ${solved?'disabled':''}>☀ Uma pista</button>${solved?`<button class="primary" data-action="next">${pageIndex===story.pages.length-1?'Escolher o final':'Próxima página'} <span>→</span></button>`:'<span class="automatic-note">Conferência automática ✦</span>'}</div></section></article><div class="reader-bottom"><button class="text-button" data-action="previous" ${pageIndex===0?'disabled':''}>← Página anterior</button><span>Uma descoberta de cada vez <span>✿</span></span></div></main>${footer()}`;}
function ending(){
  const chosen=story.endings.find(e=>e.id===progress.ending);
  return `${header()}<main class="ending-main"><span class="eyebrow">VOCÊ AJUDOU A HISTÓRIA A ACONTECER</span><h1>${escape(story.endingTitle)}</h1><p>${escape(story.endingPrompt)}</p><div class="ending-art"><img src="/assets/${chosen?.image||story.endingImage}" alt="${escape(chosen?.sentence||story.endingAlt)}"></div><div class="ending-choices">${story.endings.map(e=>`<button class="ending-choice ${progress.ending===e.id?'selected':''}" data-ending="${e.id}" aria-pressed="${progress.ending===e.id}"><span>${e.icon}</span>${e.label}</button>`).join('')}</div>${chosen?`<div class="ending-result" role="status"><span>✦ MAIS UMA HISTÓRIA PARA CONTAR! ✦</span><h2>${escape(letter(chosen.sentence))}</h2><p>${escape(story.summary)}</p><button class="text-button" data-action="ending-audio">♫ Ouvir meu final</button></div>`:''}<div class="ending-actions"><button class="secondary" data-action="restart">Ler outra vez ↻</button><button class="primary" data-action="home">Voltar à biblioteca →</button></div></main>${footer()}`;
}
function modalContent(){
  return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close icon-button" data-action="close" aria-label="Fechar opções">×</button><span class="eyebrow">CADA CRIANÇA TEM SEU TEMPO</span><h2 id="modal-title">Opções de leitura</h2><p>Prepare o livro do jeito que funciona melhor para sua criança.</p><div class="setting-row"><div><strong>Letras maiúsculas</strong><small>Alternar entre LETRAS e Letras.</small></div><button class="toggle ${settings.uppercase?'on':''}" data-action="uppercase" role="switch" aria-checked="${settings.uppercase}" aria-label="Letras maiúsculas"><span></span></button></div><div class="setting-row"><div><strong>Sons e narração</strong><small>A voz depende das opções do dispositivo.</small></div><button class="toggle ${settings.sound?'on':''}" data-action="sound" role="switch" aria-checked="${settings.sound}" aria-label="Sons e narração"><span></span></button></div><div class="progress-report"><strong>${view.startsWith('math')?`${mathUI.completed} de 7 desafios matemáticos concluídos`:`${progress.completed.length} de ${story.pages.length} páginas concluídas neste livro`}</strong><div class="mini-progress"><i style="width:${view.startsWith('math')?mathUI.completed/7*100:progress.completed.length/story.pages.length*100}%"></i></div><p>O progresso fica salvo neste navegador. Nenhum cadastro é necessário.</p></div><p class="parent-guidance">Deixe a criança tentar ler antes de ouvir a resposta. Nas montagens, ela pode arrastar ou tocar nas peças. Uma pista está sempre disponível.</p><button class="secondary full-width" data-action="${modal==='reset'?'confirm-reset':'reset'}">${modal==='reset'?'Confirmar: apagar progresso':'Recomeçar e apagar progresso'}</button>${modal==='reset'?`<p class="reset-warning">Isso apaga apenas o progresso ${view.startsWith('math')?'da matemática':'deste livro'} neste navegador.</p>`:''}</section></div>`;}
function mobileNav(){if(view==='book'||view==='math')return '';return `<nav class="mobile-nav" aria-label="Navegação principal"><button data-action="library" class="${view==='home'?'active':''}"><span aria-hidden="true">📚</span> Histórias</button><button data-action="math-home" class="${view.startsWith('math')?'active':''}"><span aria-hidden="true">🔢</span> Matemática</button></nav>`;}
function render(){
  if(renderedView==='home'){homeScroll=window.scrollY||0;app.querySelectorAll('.books-carousel').forEach(row=>shelfScroll.set(row.id,row.scrollLeft));}
  const focused=document.activeElement;
  const focusKey=['piece','choice','action','ending','page','book','level','mathAction','mathOpen','mathCounter','carousel'].find(key=>focused?.dataset?.[key]!==undefined);
  const focusValue=focusKey?focused.dataset[focusKey]:null;
  cleanupDrag();
  app.innerHTML=(view==='home'?home():view==='book'?book():view==='math-home'?header()+mathUI.home()+footer():view==='math'?header()+mathUI.exercise()+footer():view==='math-finish'?header()+mathUI.finish()+footer():ending())+mobileNav()+(modal?modalContent():'');
  if(view==='home')app.querySelectorAll('.books-carousel').forEach(row=>{row.scrollLeft=shelfScroll.get(row.id)||0;});
  renderedView=view;
  const track=app.querySelector('.chapter-track, .math-track'),active=track?.querySelector('[aria-current="step"]');if(active&&track.scrollWidth>track.clientWidth){const delta=active.getBoundingClientRect().left-track.getBoundingClientRect().left;track.scrollLeft+=delta-track.clientWidth/2+active.offsetWidth/2;}
  if(view==='book')cleanupDrag=attachDrag(app,(id,index)=>{if(solved)return;slots=placePiece(slots,id,index);feedback='';render();automatic.schedule();});
  if(view==='math')cleanupDrag=attachDrag(app,id=>mathUI.drop(id));
  const scope=modal?app.querySelector('.modal'):app;
  const target=focusKey?[...scope.querySelectorAll(`[data-${focusKey.replace(/[A-Z]/g,c=>'-'+c.toLowerCase())}]`)].find(el=>el.dataset[focusKey]===focusValue&&!el.disabled):null;
  if(target)target.focus({preventScroll:true});else if(modal)scope.querySelector('.modal-close')?.focus();
}
function answerReady(){return story.pages[pageIndex].type==='sequence'?slots.every(Boolean):selected.length>0;}
function openPage(index){automatic.cancel();stopSpeech();pageIndex=index;progress.current=index;slots=Array(story.pages[index].type==='sequence'?story.pages[index].answer.length:0).fill(null);selected=[];solved=false;feedback='';hint=false;view='book';save();render();window.scrollTo({top:0,behavior:'instant'});}
function checkAnswer(){
  if(view!=='book'||solved||!answerReady())return;
    const page=story.pages[pageIndex],answer=page.type==='sequence'?slots.map(id=>makePieces(page).find(p=>p.id===id)?.label):selected;
    if(!answerReady())return;
    if(isCorrect(page,answer)){solved=true;feedback=page.success;if(!progress.completed.includes(pageIndex))progress.completed.push(pageIndex);progress.current=Math.min(pageIndex+1,story.pages.length-1);save();chime(settings.sound);confetti();render();talk(page.success);}
    else{feedback='Vamos tentar de novo? Peça uma pista se precisar.';chime(settings.sound,false);render();app.querySelector('.activity-panel')?.classList.add('gentle-wiggle');}
}
function announce(text){document.querySelector('#announcer').textContent=text;}
function confetti(){const layer=document.createElement('div');layer.className='confetti-layer';layer.setAttribute('aria-hidden','true');for(let i=0;i<28;i++){const p=document.createElement('i');p.style.cssText=`--x:${Math.random()*100}%;--delay:${Math.random()*.3}s;--color:${['#e6aa47','#539783','#dd7e71','#9b92b9'][i%4]};--turn:${Math.random()*500}deg`;layer.append(p);}document.body.append(layer);setTimeout(()=>layer.remove(),2200);}
function talk(text){if(!settings.sound){announce('Ative o som nas opções para ouvir.');return;}const supported=speak(text,{enabled:settings.sound});if(!supported)announce('A narração não está disponível neste navegador. Você pode ler o texto na tela.');}
app.addEventListener('click',e=>{
  const button=e.target.closest('button');if(!button||button.disabled)return;
  if(view.startsWith('math')&&mathUI.handle(button.dataset))return;
  if(button.dataset.carousel){const row=app.querySelector('#books-'+button.dataset.carousel);const card=row?.querySelector('.book-card');if(row&&card){const gap=parseFloat(getComputedStyle(row).gap)||18;row.scrollBy({left:(card.getBoundingClientRect().width+gap)*Number(button.dataset.direction),behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}return;}
  if(button.dataset.level){levelFilter=button.dataset.level;render();return;}
  if(button.dataset.book){story=stories.find(item=>item.id===button.dataset.book);progress=getProgress(story);openPage(progress.completed.length===story.pages.length?0:progress.current);return;}
  if(button.dataset.piece){if(view==='math'){mathUI.drop(button.dataset.piece);return;}if(solved)return;const id=button.dataset.piece,origin=slots.indexOf(id);if(origin>=0)slots[origin]=null;else{const target=slots.indexOf(null);if(target>=0)slots[target]=id;}feedback='';chime(settings.sound,false);render();automatic.schedule();return;}
  if(button.dataset.choice){selected=[button.dataset.choice];feedback='';chime(settings.sound,false);render();automatic.schedule();return;}
  if(button.dataset.page!==undefined){openPage(Number(button.dataset.page));return;}
  if(button.dataset.ending){progress.ending=button.dataset.ending;save();chime(settings.sound);confetti();render();return;}
  const action=button.dataset.action;
  if(action==='home'){automatic.cancel();stopSpeech();view='home';modal=null;render();window.scrollTo(0,homeScroll);}
  if(action==='library'){automatic.cancel();stopSpeech();view='home';modal=null;render();app.querySelector('#library')?.scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
  if(action==='math-home'){automatic.cancel();stopSpeech();modal=null;view='math-home';render();window.scrollTo(0,0);}
  if(action==='start'){openPage(progress.completed.length===story.pages.length?0:progress.current);}
  if(action==='restart'){openPage(0);}
  if(action==='sound'){settings.sound=!settings.sound;if(!settings.sound)stopSpeech();save();render();}
  if(action==='uppercase'){settings.uppercase=!settings.uppercase;save();render();}
  if(action==='settings'){modal='settings';render();}
  if(action==='close'){modal=null;render();app.querySelector('[data-action="settings"]')?.focus();}
  if(action==='reset'){modal='reset';render();}
  if(action==='confirm-reset'&&view.startsWith('math')){modal=null;mathUI.reset();return;}
  if(action==='confirm-reset'){automatic.cancel();progress=cleanProgress({},story.pages.length,story.endings.map(e=>e.id));save();modal=null;view='home';stopSpeech();render();}
  if(action==='passage')talk(story.pages[pageIndex].readingText);
  if(action==='narrate')talk(story.pages[pageIndex].narration);
  if(action==='instruction')talk(story.pages[pageIndex].instruction+(story.pages[pageIndex].prompt?' '+story.pages[pageIndex].prompt:''));
  if(action==='hint'){hint=true;render();talk(story.pages[pageIndex].hint);}
  if(action==='previous')openPage(pageIndex-1);
  if(action==='next'){if(pageIndex===story.pages.length-1){view='ending';stopSpeech();render();window.scrollTo(0,0);}else openPage(pageIndex+1);}

  if(action==='character'){const c=characters[Number(button.dataset.index)];talk(`Olá! Eu sou ${c.name}. ${c.description}`);button.classList.remove('bounce');void button.offsetWidth;button.classList.add('bounce');}
  if(action==='fruit'){button.classList.add('counted');talk(`${Number(button.dataset.index)+1}. ${story.pages[pageIndex].countNoun||'Objeto'}.`);}
  if(action==='spark'){chime(settings.sound);confetti();}
  if(action==='ending-audio')talk(story.endings.find(e=>e.id===progress.ending)?.sentence||'');
});
document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){modal=null;render();app.querySelector('[data-action="settings"]')?.focus();}if(e.key==='Tab'){const buttons=[...app.querySelectorAll('.modal button:not([disabled]), .modal input, .modal textarea')];const first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSpeech();});
render();
